UPDATE gw_mail_log
   SET status_cd = 'SENT', sent_at = CURRENT_TIMESTAMP
 WHERE mail_id = #{mailId}

UPDATE gw_mail_log
   SET status_cd = 'FAILED',
       error_message = #{errorMessage},
       retry_cnt = #{retryCnt}
 WHERE mail_id = #{mailId}

mapper.select:
SELECT * FROM gw_mail_log WHERE 1=1
AND status_cd = #{status}
AND (LOWER(to_email) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(subject) LIKE LOWER('%' || #{keyword} || '%'))
ORDER BY queued_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM gw_mail_log WHERE 1=1
AND status_cd = #{status}
AND (LOWER(to_email) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(subject) LIKE LOWER('%' || #{keyword} || '%'))
